#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — verify the automatic CSV export at runtime, on both engines.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# Answers land in a report rather than in .env: this wizard captures
# observations, not configuration.
ENV_FILE="${ENV_FILE:-verification-export-csv.txt}"
DIST="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/dist"

SEED_SNIPPET='(async () => {
  const d = new Date(); d.setDate(d.getDate() - 1);
  const date = d.toLocaleDateString("sv");
  const visit = {
    tabId: 99, url: "https://example.com/seeded", domain: "example.com",
    metrics: { requestCount: 12, thirdPartyRequests: 4, totalResourceSize: 1.5,
               pageLoadDurationSec: 2.4, visibleDurationSec: 60, cachedPageWeight: 0.8 },
    meta: { date: d.getTime() },
    carbon: { networkCo2: 0.26, deviceCo2: 0.0024, screenCo2: 0.025,
              totalCo2: 0.287, avoidedCo2: 0.14 },
  };
  const { sessions = {} } = await chrome.storage.local.get(["sessions"]);
  sessions[date] = { date, visits: [visit], totalMetrics: {}, totalCarbon: {} };
  await chrome.storage.local.set({ sessions });
  console.log("seeded", date, Object.keys(sessions));
})()'

banner "Carbolate — automatic CSV export, both engines"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Chrome — build and load the extension"
say "Building the Chromium package into dist/ …"
( cd "$(dirname "$DIST")" && npm run build:chrome >/dev/null ) && say "built."
note "dist path (copy it, the file dialog has no address bar on macOS — press ⌘⇧G to paste it):"
printf '\n    %s%s%s\n\n' "$BOLD" "$DIST" "$RESET"
step "Open Chrome and go to  chrome://extensions"
step "Turn on 'Developer mode' (top right)."
step "Click 'Load unpacked' and pick the dist/ folder above."
pause "Loaded? Press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Chrome — arm the export"
step "Open the Carbolate side panel (click the toolbar icon)."
step "Go to the 'Paramètres' tab."
step "Turn ON 'Exporter avant de supprimer'."
step "Set 'Historique conservé' to 'Tout'."
note "Keeping everything is what lets a second day survive until we ask for its deletion."
pause "Both set? Press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Chrome — give the day before something to export"
say "The reset only exports when it would actually drop a day, so we need two."
step "Back on chrome://extensions, click the blue 'service worker' link on the Carbolate card."
step "In the DevTools console that opens, paste this and press Enter:"
printf '\n%s\n\n' "$SEED_SNIPPET"
note "It writes one page visit dated yesterday, in today's storage shape."
step "It should log:  seeded <yesterday> [ … ]"
pause "Seeded? Press Enter."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Chrome — trigger the reset and watch for the file"
step "Back in the panel, Paramètres → set 'Historique conservé' to '1 jour'."
step "A native confirmation appears naming how many days will go. Accept it."
step "Open chrome://downloads (or the downloads shelf)."
ask CHROME_DOWNLOADED "Did a CSV land in downloads? (yes/no)"
ask CHROME_FILENAME   "Exact file name as Chrome shows it:"
ask CHROME_NOTES      "Anything odd — an error in the worker console, a truncated file? (Enter for nothing)"
write_env CHROME_DOWNLOADED "$CHROME_DOWNLOADED"
write_env CHROME_FILENAME   "$CHROME_FILENAME"
write_env CHROME_NOTES      "${CHROME_NOTES:-none}"
note "Open the file if you like: the header should start with date,domain,url,requestCount,thirdPartyRequests…"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Chrome — the object URL that is never revoked"
say "The panel takes the blob path (it has createObjectURL); the worker takes a data URL."
say "A blob URL that is never revoked holds its CSV in memory until the context dies."
step "In the panel, press 'Export CSV' five times in a row."
step "Open Chrome's task manager: Window menu → Task Manager (or ⇧Esc)."
step "Find the Carbolate row and read its Memory footprint."
ask CHROME_MEMORY "Memory of the Carbolate process after five exports (e.g. '48 MB'):"
ask CHROME_MEMORY_GROWTH "Did it climb noticeably with each export? (yes/no/not sure)"
write_env CHROME_MEMORY "$CHROME_MEMORY"
write_env CHROME_MEMORY_GROWTH "$CHROME_MEMORY_GROWTH"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Firefox — build and load the extension"
say "Building the Gecko package into the same dist/ …"
( cd "$(dirname "$DIST")" && npm run build:firefox >/dev/null ) && say "built."
warn "dist/ now holds the Firefox manifest — the Chrome copy you loaded is stale from here on."
step "Open Firefox and go to  about:debugging#/runtime/this-firefox"
step "Click 'Load Temporary Add-on…'."
step "Pick the file  dist/manifest.json  (the manifest itself, not the folder)."
pause "Loaded? Press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Firefox — arm, seed, and trigger"
step "Open the Carbolate sidebar (toolbar icon, or View → Sidebar)."
step "Paramètres → turn ON 'Exporter avant de supprimer', set 'Historique conservé' to 'Tout'."
step "On about:debugging, click 'Inspect' on the Carbolate card to open its console."
step "Paste the same snippet as before and press Enter:"
printf '\n%s\n\n' "$SEED_SNIPPET"
step "Back in the sidebar: set 'Historique conservé' to '1 jour' and accept the confirmation."
step "Open the Downloads panel."
ask FIREFOX_DOWNLOADED "Did a CSV land in downloads? (yes/no)"
ask FIREFOX_FILENAME   "Exact file name as Firefox shows it:"
ask FIREFOX_NOTES      "Anything odd — console error, empty file, no prompt? (Enter for nothing)"
write_env FIREFOX_DOWNLOADED "$FIREFOX_DOWNLOADED"
write_env FIREFOX_FILENAME   "$FIREFOX_FILENAME"
write_env FIREFOX_NOTES      "${FIREFOX_NOTES:-none}"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Firefox — the blob path, five times over"
say "Firefox's event page has createObjectURL, so every export here takes the blob path."
step "In the sidebar, press 'Export CSV' five times in a row."
step "Open  about:performance  and read the Carbolate row (Memory column)."
ask FIREFOX_MEMORY "Memory reported for Carbolate after five exports:"
ask FIREFOX_MEMORY_GROWTH "Did it climb noticeably with each export? (yes/no/not sure)"
write_env FIREFOX_MEMORY "$FIREFOX_MEMORY"
write_env FIREFOX_MEMORY_GROWTH "$FIREFOX_MEMORY_GROWTH"

finish
note "Report written to $ENV_FILE — paste it back into the session, or into issue #46."
